-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        mercaro_record_id,
        mercaro_order_id,
        mercaro_customer_id,
        order_date,
        order_status,
        currency,
        order_total,
        channel,
        violation_00,
        violation_01
    from {{ ref("ecommerce__mercaro_order_extract__checked") }}
),
violations as (
    select
        'mercaro_record_id_not_null' as rule_name,
        mercaro_record_id,
        mercaro_order_id,
        mercaro_customer_id,
        order_date,
        order_status,
        currency,
        order_total,
        channel
    from quarantined
    where violation_00

    union all

    select
        'mercaro_record_id_unique' as rule_name,
        mercaro_record_id,
        mercaro_order_id,
        mercaro_customer_id,
        order_date,
        order_status,
        currency,
        order_total,
        channel
    from quarantined
    where violation_01
)

select
    rule_name,
    mercaro_record_id,
    mercaro_order_id,
    mercaro_customer_id,
    order_date,
    order_status,
    currency,
    order_total,
    channel
from violations
